package com.homeapp

import com.homeapp.features.marketplace.*
import kotlin.test.*

class MarketplacePolicyTest {
 private fun accept(free: Boolean=false)=MarketplacePolicy.apply(TrainingWorkflow(freeLaunch=free),WorkflowActor.PROVIDER,"accept")
 @Test fun freeLaunchNeverCharges() { val a=accept(true); val b=MarketplacePolicy.apply(a,WorkflowActor.CUSTOMER,"arrival"); assertEquals(FeeState.WAIVED,b.feeState); assertEquals(10000,b.balanceUgx) }
 @Test fun attendedFeeIsCapturedOnceByCustomerOnly() { val a=accept(); assertEquals(2500,a.reservedUgx); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(a,WorkflowActor.PROVIDER,"arrival")}; val b=MarketplacePolicy.apply(a,WorkflowActor.CUSTOMER,"arrival"); assertEquals(7500,b.balanceUgx); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(b,WorkflowActor.CUSTOMER,"arrival")} }
 @Test fun preArrivalCancellationReleasesReservation() { val b=MarketplacePolicy.apply(accept(),WorkflowActor.PROVIDER,"cancel","PROVIDER_UNABLE"); assertEquals(FeeState.RELEASED,b.feeState); assertEquals(10000,b.balanceUgx); assertFalse(b.arrived) }
 @Test fun postArrivalCancellationPreservesFeeAndEvidence() { val a=MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"arrival"); val b=MarketplacePolicy.apply(a,WorkflowActor.PROVIDER,"cancel","PROVIDER_UNABLE"); assertEquals(JobStage.REVIEW_REQUIRED,b.stage); assertEquals(FeeState.SETTLED,b.feeState); assertTrue(b.arrived); assertEquals(3,b.history.size); val c=MarketplacePolicy.apply(b,WorkflowActor.CUSTOMER,"confirm_diagnostic"); assertEquals(7500,c.balanceUgx); assertTrue(c.customerConfirmed) }
 @Test fun onlyReasonedReviewerCanRefundAndCannotRefundTwice() { val a=MarketplacePolicy.apply(MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"arrival"),WorkflowActor.PROVIDER,"cancel","PROVIDER_UNABLE"); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(a,WorkflowActor.PROVIDER,"release_fee","Evidence reviewed")}; val b=MarketplacePolicy.apply(a,WorkflowActor.REVIEWER,"release_fee","Customer confirms no attendance"); assertEquals(10000,b.balanceUgx); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(b,WorkflowActor.REVIEWER,"release_fee","Evidence reviewed")} }
 @Test fun quoteRequiresArrivalAndCustomerAcceptance() { assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(accept(),WorkflowActor.PROVIDER,"quote",labour=50000)}; val a=MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"arrival"); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(a,WorkflowActor.CUSTOMER,"confirm_repair")}; val b=MarketplacePolicy.apply(a,WorkflowActor.PROVIDER,"quote",labour=50000,materials=30000); assertEquals(80000,b.quoteTotalUgx); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(b,WorkflowActor.PROVIDER,"accept_quote")} }
 @Test fun reviewsRequireCustomerConfirmationAndCannotBeRepeated() { assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"review")}; val a=MarketplacePolicy.apply(MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"arrival"),WorkflowActor.CUSTOMER,"confirm_diagnostic"); val b=MarketplacePolicy.apply(a,WorkflowActor.CUSTOMER,"review"); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(b,WorkflowActor.CUSTOMER,"review")}; assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(b,WorkflowActor.PROVIDER,"cancel","PROVIDER_UNABLE")} }
 @Test fun disputedAttendanceCannotBeCancelledToBypassReview() { val a=MarketplacePolicy.apply(MarketplacePolicy.apply(accept(),WorkflowActor.CUSTOMER,"arrival"),WorkflowActor.CUSTOMER,"dispute","Technician did not attend"); assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(a,WorkflowActor.PROVIDER,"cancel","PROVIDER_UNABLE")} }
 @Test fun insufficientBalanceBlocksPaidAcceptanceOnly() { assertFailsWith<IllegalArgumentException>{MarketplacePolicy.apply(TrainingWorkflow(freeLaunch=false,balanceUgx=0),WorkflowActor.PROVIDER,"accept")}; assertEquals(FeeState.WAIVED,MarketplacePolicy.apply(TrainingWorkflow(balanceUgx=0),WorkflowActor.PROVIDER,"accept").feeState) }
}
